ALTER TABLE sessions ADD COLUMN email_otp_verified BOOLEAN NOT NULL DEFAULT FALSE;
CREATE TABLE admin_login_otps (user_id INT PRIMARY KEY, challenge_hash CHAR(64) NOT NULL UNIQUE, code_hash CHAR(64) NOT NULL, attempts INT NOT NULL DEFAULT 0, expires_at DATETIME NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
